//! Each parameter's bed status, from `beds/summary.json` as this build carries it (M12 PLAN.md,
//! P1 item 2). The file is generated by `tools/bed/summary.py` from the bed artifacts and pinned
//! by `tests/bed_summary.rs`; here it is compiled in, so a binary reports the statuses it was
//! built with, and the report says which file that was by its sha256.
//!
//! The Results screen renders a parameter only when its status here is PASS (M12 gate (b)).
//! Nothing in this module judges a parameter: it reads the file.

use std::sync::OnceLock;

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// `beds/summary.json`, compiled in. Committed with `-text` (`.gitattributes`), so these are the
/// bytes the script wrote on every checkout.
pub const SUMMARY: &str = include_str!("../../../../beds/summary.json");

/// A parameter's bed status.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub enum BedStatus {
    /// Every check on every artifact named final held.
    #[serde(rename = "PASS")]
    Pass,
    /// A check did not hold, an artifact is missing, or no artifact scores it: `reasons` says
    /// which. Not rendered (M12 gate (b)).
    #[serde(rename = "FAIL")]
    Fail,
}

/// One parameter's entry: its status, why it failed (empty for a PASS), and the summary's notes
/// (the marks, the `wide` rules, what was not tested).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct BedParameter {
    pub status: BedStatus,
    pub reasons: Vec<String>,
    pub notes: Vec<String>,
}

impl BedParameter {
    pub fn passed(&self) -> bool {
        self.status == BedStatus::Pass
    }
}

/// Every parameter the report carries, by its JSON name.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct BedParameters {
    pub spl_db: BedParameter,
    pub edt_s: BedParameter,
    pub t20_s: BedParameter,
    pub t30_s: BedParameter,
    pub c50_db: BedParameter,
    pub c80_db: BedParameter,
    pub d50: BedParameter,
    pub ts_s: BedParameter,
    /// The speech transmission index (`sti` on an SPPS point receiver).
    pub sti: BedParameter,
    /// Sound strength G (`g_db` on a band).
    pub g_db: BedParameter,
    /// The A-weighted level (`aggregate.dba`).
    pub dba: BedParameter,
}

impl BedParameters {
    /// The eleven in the report's order, with their JSON names.
    pub fn named(&self) -> [(&'static str, &BedParameter); 11] {
        [
            ("spl_db", &self.spl_db),
            ("edt_s", &self.edt_s),
            ("t20_s", &self.t20_s),
            ("t30_s", &self.t30_s),
            ("c50_db", &self.c50_db),
            ("c80_db", &self.c80_db),
            ("d50", &self.d50),
            ("ts_s", &self.ts_s),
            ("sti", &self.sti),
            ("g_db", &self.g_db),
            ("dba", &self.dba),
        ]
    }

    fn all(status: BedStatus, reason: &str) -> Self {
        let p = || BedParameter {
            status,
            reasons: vec![reason.to_string()],
            notes: Vec::new(),
        };
        BedParameters {
            spl_db: p(),
            edt_s: p(),
            t20_s: p(),
            t30_s: p(),
            c50_db: p(),
            c80_db: p(),
            d50: p(),
            ts_s: p(),
            sti: p(),
            g_db: p(),
            dba: p(),
        }
    }
}

/// What the report carries: the summary's sha256 and its statuses.
#[derive(Clone, Debug, PartialEq, Serialize, JsonSchema)]
pub struct BedReport {
    /// The sha256 of `beds/summary.json` as compiled in.
    pub summary_sha256: String,
    /// The summary that holds the evidence: path, artifacts and their sha256, the rule.
    pub summary: String,
    pub parameters: BedParameters,
}

impl BedReport {
    /// True only when every parameter passed: the report's `validated_by_bed`.
    pub fn all_passed(&self) -> bool {
        self.parameters.named().iter().all(|(_, p)| p.passed())
    }
}

#[derive(Deserialize)]
struct SummaryFile {
    parameters: BedParameters,
}

/// The statuses of `text`, a summary; a summary that does not read makes every parameter FAIL,
/// naming why.
pub fn parse(text: &str) -> BedParameters {
    match serde_json::from_str::<SummaryFile>(text) {
        Ok(s) => s.parameters,
        Err(e) => BedParameters::all(
            BedStatus::Fail,
            &format!("beds/summary.json does not read: {e}"),
        ),
    }
}

/// [`SUMMARY`]'s report, read once.
pub fn report() -> &'static BedReport {
    static R: OnceLock<BedReport> = OnceLock::new();
    R.get_or_init(|| BedReport {
        summary_sha256: format!("{:x}", Sha256::digest(SUMMARY.as_bytes())),
        summary: "beds/summary.json".to_string(),
        parameters: parse(SUMMARY),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_compiled_in_summary_reads_and_names_every_parameter_once() {
        let r = report();
        let v: serde_json::Value = serde_json::from_str(SUMMARY).unwrap();
        let mut keys: Vec<&str> = v["parameters"]
            .as_object()
            .unwrap()
            .keys()
            .map(String::as_str)
            .collect();
        let mut names: Vec<&str> = r.parameters.named().iter().map(|(n, _)| *n).collect();
        keys.sort_unstable();
        names.sort_unstable();
        assert_eq!(keys, names, "the summary's parameters, each once");
        for (name, p) in r.parameters.named() {
            assert_eq!(
                serde_json::to_value(p.status).unwrap(),
                v["parameters"][name]["status"],
                "{name}"
            );
        }
    }

    #[test]
    fn the_sha256_is_that_of_the_committed_file() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../beds/summary.json");
        let bytes = std::fs::read(path).unwrap();
        assert_eq!(
            report().summary_sha256,
            format!("{:x}", Sha256::digest(&bytes))
        );
    }

    #[test]
    fn a_summary_that_does_not_read_fails_every_parameter() {
        for bad in ["", "{}", r#"{"parameters": {"spl_db": {}}}"#] {
            let p = parse(bad);
            for (name, q) in p.named() {
                assert_eq!(q.status, BedStatus::Fail, "{bad:?} {name}");
                assert!(q.reasons[0].contains("does not read"), "{bad:?} {name}");
            }
        }
        // An unknown parameter is refused, not ignored.
        let mut v: serde_json::Value = serde_json::from_str(SUMMARY).unwrap();
        v["parameters"]["lf"] = v["parameters"]["spl_db"].clone();
        assert_eq!(parse(&v.to_string()).spl_db.status, BedStatus::Fail);
    }

    #[test]
    fn validated_by_bed_is_every_parameter_passing() {
        let mut v: serde_json::Value = serde_json::from_str(SUMMARY).unwrap();
        for (_, p) in v["parameters"].as_object_mut().unwrap() {
            p["status"] = "PASS".into();
        }
        let all = BedReport {
            summary_sha256: String::new(),
            summary: String::new(),
            parameters: parse(&v.to_string()),
        };
        assert!(all.all_passed());
        let mut one = all.clone();
        one.parameters.dba.status = BedStatus::Fail;
        assert!(!one.all_passed());
    }
}
